import 'package:injectable/injectable.dart';import 'package:smart_coach_new/core/network/rest_client.dart';import 'package:smart_coach_new/core/network/safe_request.dart';import 'package:smart_coach_new/core/utils/prefs.dart';import 'package:smart_coach_new/features/user_management/data/models/approve_or_reject_response.dart';import 'package:smart_coach_new/features/user_management/data/models/approve_user_request.dart';import 'package:smart_coach_new/features/user_management/data/models/bulk_approve_user_request.dart';import 'package:smart_coach_new/features/user_management/data/models/general_response.dart';import 'package:smart_coach_new/features/user_management/data/models/user_model.dart';import 'package:smart_coach_new/features/user_management/domain/entities/pending_users_request.dart';@injectableclass UserManagementRemoteDataSourceImpl {	final RestClient restClient;	final Prefs prefs;	UserManagementRemoteDataSourceImpl(this.restClient, this.prefs);	Future<List<UserModel>> fetchUsers({PendingUsersRequest? request}) async {		return safeRequest(() async {			final Map<String, dynamic> queryParams = {};			if (request != null) {				if (request.statusList != null && request.statusList!.isNotEmpty) {					for (final status in request.statusList!) {						queryParams.putIfAbsent('status', () => []).add(status);					}				}				if (request.organizationTypeList != null &&						request.organizationTypeList!.isNotEmpty) {					for (final orgType in request.organizationTypeList!) {						queryParams.putIfAbsent('organisation_type', () => []).add(orgType);					}				}				if (request.fromDate != null) {					queryParams['from_date'] = request.fromDate!;				}				if (request.toDate != null) {					queryParams['to_date'] = request.toDate!;				}			}			final response = await restClient.getPendingUsersNew(				prefs.userId!,				queryParams,			);			if (!response.success || response.data == null) {				throw Exception(response.message);			}			return response.data!;		});		// return safeRequest(() async {		//   final UserManagementResponse userManagementResponse =		//       await restClient.getPendingUsers(prefs.userId!,		//           status: request?.status,		//           organisationType: request?.organisationType,		//           fromDate: request?.fromDate,		//           toDate: request?.toDate);		//   if (!userManagementResponse.success ||		//       userManagementResponse.data == null) {		//     throw Exception(userManagementResponse.message);		//   }		//   return userManagementResponse.data!;		// });	}	Future<String> approveOrRejectUsers(			List<ApproveUserRequest> usersList) async {		return safeRequest(() async {			final ApproveOrRejectResponse approveOrRejectResponse;			if (usersList.length == 1) {				approveOrRejectResponse = await restClient.approveUser(						prefs.userId!, usersList.first.toJson());			} else {				approveOrRejectResponse = await restClient.approveBulkUser(						prefs.userId!, BulkApproveRequest(users: usersList).toJson());			}			if (!approveOrRejectResponse.success) {				throw Exception(approveOrRejectResponse.message);			}			return approveOrRejectResponse.message;		});	}	Future<String> changeRole(int? roleId, int? targetUserId) async {		return safeRequest(() async {			final GeneralResponse generalResponse = await restClient.changeRole({				'role_id': roleId,				'target_user_id': targetUserId,			});			if (!generalResponse.success) {				throw Exception(generalResponse.message);			}			return generalResponse.message;		});	}	Future<String> changeTrain(int? targetUserId, List<int>? trainIds) async {		return safeRequest(() async {			final GeneralResponse generalResponse = await restClient.changeTrain({				'user_id': targetUserId,				'train_ids': trainIds,			});			if (!generalResponse.success) {				throw Exception(generalResponse.message);			}			return generalResponse.message;		});	}}